<?php
declare(strict_types=1);

function benchmark_ready(PDO $pdo): bool
{
    try{$pdo->query('SELECT 1 FROM benchmark_configuracoes LIMIT 1');return true;}catch(Throwable){return false;}
}

function benchmark_slug(string $value): string
{
    $value=mb_strtolower(trim($value),'UTF-8');$ascii=@iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$value);
    if(is_string($ascii))$value=$ascii;
    return trim(preg_replace('/[^a-z0-9]+/','-',$value)?:'','-');
}

function benchmark_uploads(array $input): array
{
    if(!isset($input['name']))return [];
    if(!is_array($input['name']))return [$input];
    $files=[];foreach($input['name'] as $i=>$name)$files[]=['name'=>$name,'tmp_name'=>$input['tmp_name'][$i]??'','error'=>$input['error'][$i]??UPLOAD_ERR_NO_FILE,'size'=>$input['size'][$i]??0];
    return $files;
}

function benchmark_store_evidence_files(PDO $pdo,int $configurationId,int $valueId,array $input,array $meta): void
{
    $files=benchmark_uploads($input);if(!$files)return;
    $allowed=['image/jpeg'=>['imagem','jpg',10*1024*1024],'image/png'=>['imagem','png',10*1024*1024],'image/webp'=>['imagem','webp',10*1024*1024],'application/pdf'=>['pdf','pdf',20*1024*1024]];
    $root=dirname(__DIR__).'/public/assets/uploads/benchmark/'.date('Y/m');
    if(!is_dir($root)&&!mkdir($root,0775,true)&&!is_dir($root))throw new RuntimeException('Não foi possível preparar a pasta de evidências.');
    $finfo=new finfo(FILEINFO_MIME_TYPE);$insert=$pdo->prepare('INSERT INTO benchmark_evidencias(titulo,tipo,arquivo,legenda,credito,origem,posicao_captura,escopo,capturado_em,criado_por) VALUES(?,?,?,?,?,?,?,?,?,?)');$linkConfig=$pdo->prepare('INSERT IGNORE INTO benchmark_evidencia_configuracoes(evidencia_id,configuracao_id) VALUES(?,?)');$linkValue=$pdo->prepare('INSERT IGNORE INTO benchmark_evidencia_valores(evidencia_id,valor_id,ordem) VALUES(?,?,?)');
    foreach($files as $order=>$file){$error=(int)($file['error']??UPLOAD_ERR_NO_FILE);if($error===UPLOAD_ERR_NO_FILE)continue;if($error!==UPLOAD_ERR_OK)throw new RuntimeException('Falha ao receber uma evidência.');$tmp=(string)$file['tmp_name'];$mime=(string)$finfo->file($tmp);if(!isset($allowed[$mime]))throw new RuntimeException('Envie somente JPG, PNG, WEBP ou PDF como evidência.');[$type,$ext,$limit]=$allowed[$mime];$size=(int)($file['size']??0);if($size<1||$size>$limit)throw new RuntimeException('Uma evidência excede o tamanho permitido.');$name=bin2hex(random_bytes(18)).'.'.$ext;$absolute=$root.'/'.$name;if(!move_uploaded_file($tmp,$absolute))throw new RuntimeException('Não foi possível guardar uma evidência.');$relative='/public/assets/uploads/benchmark/'.date('Y/m').'/'.$name;$title=trim((string)($meta['titulo']??''))?:pathinfo((string)$file['name'],PATHINFO_FILENAME);$insert->execute([mb_substr($title,0,200),$type,$relative,trim((string)($meta['legenda']??''))?:null,trim((string)($meta['credito']??''))?:null,trim((string)($meta['origem']??''))?:null,trim((string)($meta['posicao_captura']??''))?:null,trim((string)($meta['escopo']??''))?:null,trim((string)($meta['capturado_em']??''))?:null,(int)(user()['id']??0)]);$id=(int)$pdo->lastInsertId();$linkConfig->execute([$id,$configurationId]);$linkValue->execute([$id,$valueId,$order]);}
}

function benchmark_store_evidence_link(PDO $pdo,int $configurationId,int $valueId,array $meta): void
{
    $url=trim((string)($meta['evidencia_url']??''));if($url==='')return;
    if(!filter_var($url,FILTER_VALIDATE_URL)||!in_array(strtolower((string)parse_url($url,PHP_URL_SCHEME)),['http','https'],true))throw new RuntimeException('Informe uma URL de evidência HTTP ou HTTPS válida.');
    $stmt=$pdo->prepare('INSERT INTO benchmark_evidencias(titulo,tipo,url,legenda,credito,origem,posicao_captura,escopo,capturado_em,criado_por) VALUES(?,?,?,?,?,?,?,?,?,?)');
    $stmt->execute([mb_substr(trim((string)($meta['titulo']??''))?:'Evidência externa',0,200),'link',$url,trim((string)($meta['legenda']??''))?:null,trim((string)($meta['credito']??''))?:null,trim((string)($meta['origem']??''))?:null,trim((string)($meta['posicao_captura']??''))?:null,trim((string)($meta['escopo']??''))?:null,trim((string)($meta['capturado_em']??''))?:null,(int)(user()['id']??0)]);
    $id=(int)$pdo->lastInsertId();$pdo->prepare('INSERT IGNORE INTO benchmark_evidencia_configuracoes(evidencia_id,configuracao_id) VALUES(?,?)')->execute([$id,$configurationId]);$pdo->prepare('INSERT IGNORE INTO benchmark_evidencia_valores(evidencia_id,valor_id,ordem) VALUES(?,?,999)')->execute([$id,$valueId]);
}

function handle_benchmark_post(string $route,string $method): void
{
    if($route!=='benchmark'||$method!=='POST')return;
    verify_csrf();$pdo=db();$action=(string)($_POST['action']??'');
    try{
        if(!$pdo||!benchmark_ready($pdo))throw new RuntimeException('Execute a migração 20261021_033 para habilitar o módulo.');
        $permission=str_starts_with($action,'delete_')?'delete':(str_starts_with($action,'update_')||$action==='save_value'?'update':'create');
        if(!can('benchmark',$permission))throw new RuntimeException('Seu perfil não permite realizar esta ação.');
        if($action==='save_category'){
            $id=(int)($_POST['id']??0);$name=trim((string)($_POST['nome']??''));if($name==='')throw new RuntimeException('Informe o nome da categoria.');$slug=benchmark_slug($name);$allowedIcons=['bi-grid','bi-display','bi-speedometer2','bi-shield-check','bi-gear','bi-lightbulb','bi-camera','bi-images','bi-diagram-3','bi-wrench-adjustable','bi-cpu','bi-battery-charging','bi-fuel-pump','bi-thermometer-half','bi-wifi','bi-phone','bi-person-badge','bi-box-seam','bi-sliders','bi-truck-front'];$icon=trim((string)($_POST['icone']??''));if(!in_array($icon,$allowedIcons,true))$icon='bi-grid';$values=[$name,$slug,trim((string)($_POST['descricao']??''))?:null,$icon,max(0,(int)($_POST['ordem']??0)),(int)isset($_POST['ativo'])];
            if($id){$values[]=$id;$pdo->prepare('UPDATE benchmark_categorias SET nome=?,slug=?,descricao=?,icone=?,ordem=?,ativo=? WHERE id=?')->execute($values);}else{$pdo->prepare('INSERT INTO benchmark_categorias(nome,slug,descricao,icone,ordem,ativo) VALUES(?,?,?,?,?,?)')->execute($values);}flash('success','Categoria de benchmark salva.');
        }elseif($action==='save_attribute'){
            $id=(int)($_POST['id']??0);$category=(int)($_POST['categoria_id']??0);$name=trim((string)($_POST['nome']??''));$type=(string)($_POST['tipo']??'texto');$criterion=(string)($_POST['criterio']??'neutro');if(!$category||$name==='')throw new RuntimeException('Informe categoria e nome do atributo.');if(!in_array($type,['booleano','numero','texto','selecao_unica','selecao_multipla'],true))throw new RuntimeException('Tipo de atributo inválido.');if(!in_array($criterion,['maior_melhor','menor_melhor','atende_requisito','qualitativo','neutro'],true))$criterion='neutro';$values=[$category,$name,benchmark_slug($name),trim((string)($_POST['descricao']??''))?:null,$type,trim((string)($_POST['unidade']??''))?:null,$criterion,max(0,min(4,(int)($_POST['casas_decimais']??0))),max(0,(int)($_POST['ordem']??0)),(int)isset($_POST['ativo'])];if($id){$values[]=$id;$pdo->prepare('UPDATE benchmark_atributos SET categoria_id=?,nome=?,slug=?,descricao=?,tipo=?,unidade=?,criterio=?,casas_decimais=?,ordem=?,ativo=? WHERE id=?')->execute($values);}else{$pdo->prepare('INSERT INTO benchmark_atributos(categoria_id,nome,slug,descricao,tipo,unidade,criterio,casas_decimais,ordem,ativo) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute($values);}flash('success','Atributo homologado com sucesso.');
        }elseif($action==='save_configuration'){
            $id=(int)($_POST['id']??0);$model=(int)($_POST['modelo_id']??0);$name=trim((string)($_POST['nome']??''));if(!$model||$name==='')throw new RuntimeException('Selecione o modelo e informe o nome da configuração.');$status=(string)($_POST['situacao_comercial']??'nao_confirmado');if(!in_array($status,['linha_atual','historico','anunciado','nao_confirmado'],true))$status='nao_confirmado';$values=[$model,$name,trim((string)($_POST['ano_modelo']??''))?:null,trim((string)($_POST['ano_fabricacao']??''))?:null,trim((string)($_POST['geracao']??''))?:null,trim((string)($_POST['versao_comercial']??''))?:null,trim((string)($_POST['cabine']??''))?:null,trim((string)($_POST['tracao']??''))?:null,trim((string)($_POST['suspensao']??''))?:null,trim((string)($_POST['pacote']??''))?:null,trim((string)($_POST['mercado']??''))?:'Brasil',trim((string)($_POST['aplicacao']??''))?:null,trim((string)($_POST['data_referencia']??''))?:null,$status,trim((string)($_POST['descricao']??''))?:null,(int)isset($_POST['ativo']),(int)(user()['id']??0)];if($id){$values[]=$id;$pdo->prepare('UPDATE benchmark_configuracoes SET modelo_id=?,nome=?,ano_modelo=?,ano_fabricacao=?,geracao=?,versao_comercial=?,cabine=?,tracao=?,suspensao=?,pacote=?,mercado=?,aplicacao=?,data_referencia=?,situacao_comercial=?,descricao=?,ativo=?,atualizado_por=? WHERE id=?')->execute($values);}else{$pdo->prepare('INSERT INTO benchmark_configuracoes(modelo_id,nome,ano_modelo,ano_fabricacao,geracao,versao_comercial,cabine,tracao,suspensao,pacote,mercado,aplicacao,data_referencia,situacao_comercial,descricao,ativo,criado_por) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute($values);}flash('success','Configuração salva para comparação.');
        }elseif($action==='save_value'){
            $configuration=(int)($_POST['configuracao_id']??0);$attribute=(int)($_POST['atributo_id']??0);if(!$configuration||!$attribute)throw new RuntimeException('Selecione configuração e atributo.');$status=(string)($_POST['status_dado']??'informado');$availability=(string)($_POST['disponibilidade']??'nao_confirmado');$review=(string)($_POST['status_revisao']??'rascunho');$origin=(string)($_POST['origem_registro']??'manual');$pdo->beginTransaction();$existing=$pdo->prepare('SELECT * FROM benchmark_valores WHERE configuracao_id=? AND atributo_id=?');$existing->execute([$configuration,$attribute]);$before=$existing->fetch();if($before)$pdo->prepare('INSERT INTO benchmark_valor_historico(valor_id,acao,snapshot_json,usuario_id) VALUES(?,?,?,?)')->execute([(int)$before['id'],'atualizacao',json_encode($before,JSON_UNESCAPED_UNICODE),(int)(user()['id']??0)]);$sql='INSERT INTO benchmark_valores(configuracao_id,atributo_id,valor_texto,valor_numero,valor_booleano,unidade,status_dado,disponibilidade,status_revisao,origem,confianca,observacao,criado_por,atualizado_por) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE valor_texto=VALUES(valor_texto),valor_numero=VALUES(valor_numero),valor_booleano=VALUES(valor_booleano),unidade=VALUES(unidade),status_dado=VALUES(status_dado),disponibilidade=VALUES(disponibilidade),status_revisao=VALUES(status_revisao),origem=VALUES(origem),confianca=VALUES(confianca),observacao=VALUES(observacao),atualizado_por=VALUES(atualizado_por)';$bool=$_POST['valor_booleano']??'';$pdo->prepare($sql)->execute([$configuration,$attribute,trim((string)($_POST['valor_texto']??''))?:null,($_POST['valor_numero']??'')!==''?(float)$_POST['valor_numero']:null,$bool===''?null:(int)$bool,trim((string)($_POST['unidade']??''))?:null,$status,$availability,$review,$origin,max(0,min(100,(int)($_POST['confianca']??50))),trim((string)($_POST['observacao']??''))?:null,(int)(user()['id']??0),(int)(user()['id']??0)]);$lookup=$pdo->prepare('SELECT id FROM benchmark_valores WHERE configuracao_id=? AND atributo_id=?');$lookup->execute([$configuration,$attribute]);$valueId=(int)$lookup->fetchColumn();benchmark_store_evidence_files($pdo,$configuration,$valueId,$_FILES['evidencias']??[],$_POST);benchmark_store_evidence_link($pdo,$configuration,$valueId,$_POST);$pdo->commit();flash('success','Observação e galeria salvas.');
        }elseif($action==='save_analysis'){
            $title=trim((string)($_POST['titulo']??''));$fact=trim((string)($_POST['fato_observado']??''));if($title===''||$fact==='')throw new RuntimeException('Informe o título e o fato observado.');$type=(string)($_POST['tipo']??'investigacao');$impact=(string)($_POST['impacto']??'medio');$priority=(string)($_POST['prioridade']??'P3');$status=(string)($_POST['status']??'rascunho');$pdo->beginTransaction();$pdo->prepare('INSERT INTO benchmark_analises(titulo,tipo,impacto,prioridade,status,area_responsavel,fato_observado,citacao_motorista,interpretacao_tecnica,proximo_passo,prazo,criado_por) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$title,$type,$impact,$priority,$status,trim((string)($_POST['area_responsavel']??''))?:null,$fact,trim((string)($_POST['citacao_motorista']??''))?:null,trim((string)($_POST['interpretacao_tecnica']??''))?:null,trim((string)($_POST['proximo_passo']??''))?:null,trim((string)($_POST['prazo']??''))?:null,(int)(user()['id']??0)]);$id=(int)$pdo->lastInsertId();$link=$pdo->prepare('INSERT IGNORE INTO benchmark_analise_configuracoes(analise_id,configuracao_id) VALUES(?,?)');foreach(array_unique(array_map('intval',(array)($_POST['configuracoes']??[]))) as $config)if($config)$link->execute([$id,$config]);$pdo->commit();flash('success','Análise registrada e vinculada às configurações.');
        }elseif($action==='delete_configuration'){
            $id=(int)($_POST['id']??0);$uses=$pdo->prepare('SELECT (SELECT COUNT(*) FROM benchmark_valores WHERE configuracao_id=?)+(SELECT COUNT(*) FROM benchmark_analise_configuracoes WHERE configuracao_id=?)');$uses->execute([$id,$id]);if((int)$uses->fetchColumn()>0)throw new RuntimeException('A configuração possui observações ou análises. Inative-a para preservar o histórico.');$pdo->prepare('DELETE FROM benchmark_configuracoes WHERE id=?')->execute([$id]);flash('success','Configuração excluída.');
        }else throw new RuntimeException('Ação de benchmark inválida.');
    }catch(PDOException $e){if($pdo&&$pdo->inTransaction())$pdo->rollBack();flash('error',$e->getCode()==='23000'?'Já existe um cadastro igual ou há vínculos inválidos.':'Não foi possível salvar o benchmark no banco.');}
    catch(Throwable $e){if($pdo&&$pdo->inTransaction())$pdo->rollBack();flash('error',$e->getMessage());}
    redirect('benchmark');
}

function load_benchmark_page(): array
{
    $pdo=db();$data=['ready'=>false,'categories'=>[],'attributes'=>[],'configurations'=>[],'values'=>[],'analyses'=>[],'models'=>[],'stats'=>[]];if(!$pdo||!benchmark_ready($pdo))return $data;$data['ready']=true;
    $data['categories']=$pdo->query('SELECT bc.*,(SELECT COUNT(*) FROM benchmark_atributos ba WHERE ba.categoria_id=bc.id AND ba.ativo=1) atributos FROM benchmark_categorias bc ORDER BY bc.ordem,bc.nome')->fetchAll();
    $data['attributes']=$pdo->query('SELECT ba.*,bc.nome categoria_nome FROM benchmark_atributos ba JOIN benchmark_categorias bc ON bc.id=ba.categoria_id ORDER BY bc.ordem,ba.ordem,ba.nome')->fetchAll();
    $data['models']=$pdo->query('SELECT m.id,m.nome,f.nome familia_nome,ma.nome marca_nome,f.tipo_veiculo FROM modelos m JOIN familias f ON f.id=m.familia_id JOIN marcas ma ON ma.id=f.marca_id WHERE m.ativo=1 ORDER BY ma.nome,f.nome,m.nome')->fetchAll();
    $data['configurations']=$pdo->query("SELECT bc.*,m.nome modelo_nome,m.imagem modelo_imagem,f.nome familia_nome,ma.nome marca_nome,ma.slug marca_slug,(SELECT COUNT(*) FROM benchmark_valores bv WHERE bv.configuracao_id=bc.id) observacoes,(SELECT COUNT(*) FROM benchmark_evidencia_configuracoes bec WHERE bec.configuracao_id=bc.id) evidencias FROM benchmark_configuracoes bc JOIN modelos m ON m.id=bc.modelo_id JOIN familias f ON f.id=m.familia_id JOIN marcas ma ON ma.id=f.marca_id ORDER BY bc.ativo DESC,ma.nome,f.nome,m.nome,bc.nome")->fetchAll();
    $values=$pdo->query("SELECT bv.*,ba.nome atributo_nome,ba.tipo atributo_tipo,ba.criterio,ba.categoria_id,bc.nome categoria_nome,c.nome configuracao_nome,m.nome modelo_nome,ma.nome marca_nome FROM benchmark_valores bv JOIN benchmark_atributos ba ON ba.id=bv.atributo_id JOIN benchmark_categorias bc ON bc.id=ba.categoria_id JOIN benchmark_configuracoes c ON c.id=bv.configuracao_id JOIN modelos m ON m.id=c.modelo_id JOIN familias f ON f.id=m.familia_id JOIN marcas ma ON ma.id=f.marca_id ORDER BY bc.ordem,ba.ordem")->fetchAll();$galleryStmt=$pdo->prepare('SELECT be.* FROM benchmark_evidencias be JOIN benchmark_evidencia_valores bev ON bev.evidencia_id=be.id WHERE bev.valor_id=? ORDER BY bev.ordem,be.id');foreach($values as &$value){$galleryStmt->execute([(int)$value['id']]);$value['gallery']=$galleryStmt->fetchAll();}$data['values']=$values;
    $data['analyses']=$pdo->query("SELECT a.*,(SELECT GROUP_CONCAT(CONCAT(ma.nome,' ',m.nome) ORDER BY ma.nome,m.nome SEPARATOR ' · ') FROM benchmark_analise_configuracoes ac JOIN benchmark_configuracoes c ON c.id=ac.configuracao_id JOIN modelos m ON m.id=c.modelo_id JOIN familias f ON f.id=m.familia_id JOIN marcas ma ON ma.id=f.marca_id WHERE ac.analise_id=a.id) configuracoes_nomes FROM benchmark_analises a ORDER BY FIELD(a.status,'em_analise','validada','planejada','rascunho','concluida','arquivada'),a.atualizado_em DESC")->fetchAll();
    $validated=0;$evidence=0;foreach($values as $v){if($v['status_revisao']==='validado')$validated++;$evidence+=count($v['gallery']);}$data['stats']=['configurations'=>count($data['configurations']),'attributes'=>count($data['attributes']),'observations'=>count($values),'validated'=>$validated,'evidence'=>$evidence,'coverage'=>count($data['configurations'])&&count($data['attributes'])?(int)round(count($values)/(count($data['configurations'])*count($data['attributes']))*100):0];
    return $data;
}
